# Delfinel (Carpathia No. 10129) sculpted from nothing on the skeleton and clips of the game's own export of it
# (sculptkit.py); the game has no sculptor for it, so its export is a body generated by rule and only its bones,
# clips and size are kept:
#   blender --background --factory-startup --python sculpts/delfinel.py -- <the export's Delfinel.glb> <out.glb>
#
# From the picture (docs/art/reference/gemini/carpathia/10129-Delfinel.jpg) and the brief (CP-dex-3, "129. Delfinel"):
# a small, plump dolphin calf, blue-grey on top and pale cream below, the cream running from the lower jaw and the
# cheeks under the eye along the belly and turning a warm tan toward the tail; a big round head; a short round beak
# and under it a wide open smile, dark red inside with a pink tongue; a big round eye high on the head, a white glint;
# a few cream spots behind the eye and on the flank; a little dorsal fin curled over into a spiral; grey pectoral
# fins swept back and down; a fluke of two lobes. The picture's leap and its wave and droplets are dropped: the calf
# swims level at the export's height.
#
# Written to be grown from (delfinora.py takes the frame through sibling("delfinel")); the calls are under __main__.
import os, sys, math
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from sculptkit import (Kit, ell, tube, blade, srgb, inside, unit, polygon, eye_look, outward, args)

GREY, CREAM, TAN, SPOT = "#8A9BA8", "#F3ECCD", "#D6C4AF", "#F1EAC6"
MOUTH_RIM, MOUTH_IN, TONGUE = "#2C2230", "#8E3646", "#EE8E98"
WHITE, IRIS, PUPIL, INK = srgb("#F7F7F4"), srgb("#3E4656"), srgb("#14161E"), srgb("#1E2230")


def at_surface(C, R, d):
    """The point of an ellipsoid (centre C, radii R) in a direction d from its centre."""
    d = np.array(d, float)
    return np.array(C, float) + d / np.linalg.norm(d / np.array(R, float))


def flat(c, d, half, up=(0, 0, 1.0), roll=0.0, deform=None):
    """A flattened ellipsoid lying along d: half sizes (along, across, thick), its face toward up, rolled about d."""
    d = unit(*d)
    s = np.cross(d, up); s /= np.linalg.norm(s)
    n = np.cross(s, d)
    r = math.radians(roll)
    s, n = s * math.cos(r) + n * math.sin(r), n * math.cos(r) - s * math.sin(r)
    V, F = ell((0, 0, 0), (half[1], half[0], half[2]), deform=deform)
    return V @ np.stack([s, d, n]) + np.array(c, float), F


def taper(k_):
    def f(V):
        V = V.copy(); V[:, 0] *= 1.0 - k_ * np.clip(V[:, 1], 0, 1) ** 1.3; return V
    return f


def pectorals(k, root, d, half, color, roll=-22):
    """Two pectoral fins swept back, out and down, their faces turned toward the front and up."""
    for sx in (1, -1):
        r = np.array(root, float) * (sx, 1, 1)
        dd = np.array(d, float) * (sx, 1, 1)
        c = r + unit(*dd) * half[0] * 0.85
        k.add(f"fin{'RL'[sx < 0]}", flat(c, dd, half, up=(0, -0.5, 1.0), roll=roll * sx, deform=taper(0.5)),
              color, f"fin{'RL'[sx < 0]}")


def fluke(k, tip, half, color, rise=0.4):
    """A fluke of two lobes back, out and rising a little, so the back camera sees their faces."""
    for sx in (1, -1):
        d = unit(0.75 * sx, 0.6, rise)
        k.add(f"fluke{'RL'[sx < 0]}", flat(np.array(tip, float) + d * half[0] * 0.8, d, half, up=(0, -0.9, 0.5),
                                          deform=taper(0.55)), color, "tailFin")


def curl_fin(k, base, h, color, lean=32, name="dorsal"):
    """A dorsal fin that rises, sweeps back and curls over into a spiral at its tip, leaning toward +X."""
    l = math.radians(lean)
    pts, radii = [], []
    for (yy, zz), r in zip(((0.0, 0.0), (0.035, 0.065), (0.085, 0.1), (0.13, 0.095), (0.145, 0.06), (0.125, 0.04),
                            (0.1, 0.05)), (0.055, 0.044, 0.034, 0.027, 0.022, 0.019, 0.017)):
        pts.append(np.array(base, float) + np.array([zz * h * math.sin(l), yy * h, zz * h * math.cos(l)]))
        radii.append(r * h)
    k.add(name, outward(blade(pts, radii, (math.cos(l), 0, -math.sin(l)), 0.45)), color, "dorsal", fuse=False,
          surface="scales")


def round_eye(u, v):
    """A big round eye: a white ring, a dark grey-blue iris, a black pupil, a big glint and a small one."""
    r = np.sqrt(u * u + v * v)
    c = np.tile(WHITE, (len(u), 1))
    c[((u + 0.05) / 0.72) ** 2 + ((v + 0.02) / 0.78) ** 2 < 1] = IRIS
    c[((u + 0.05) / 0.42) ** 2 + ((v + 0.0) / 0.48) ** 2 < 1] = PUPIL
    c[np.hypot(u + 0.22, v - 0.3) < 0.2] = (1.0, 1.0, 1.0)
    c[np.hypot(u - 0.2, v + 0.32) < 0.09] = (1.0, 1.0, 1.0)
    c[r > 0.88] = INK
    return c


def lay_eyes(k, E, d, half, lid, open_look=round_eye, outline=None):
    def eyes(state):
        k.decal(E, d, half, eye_look(state, open_look, srgb(lid), INK, line=0.16), up=unit(0, 0.25, 1),
                eps=0.004, rings=20, segs=56, mirror=True, outline=outline)
    return eyes


def delfinel(src, out):
    k = Kit(src, coat="scales")
    # --- a plump spindle: a big round head, the torso, the tail stock tapering behind ---------------------------
    HC, HR = np.array([0, -0.13, 0.33]), np.array([0.15, 0.165, 0.148])
    k.add("head", ell(HC, HR, rot=(4, 0, 0)), GREY, "body")
    k.add("torso", ell((0, 0.03, 0.31), (0.152, 0.2, 0.152)), GREY, "body")
    k.add("rear", tube([(0, 0.12, 0.31), (0, 0.24, 0.32)], [0.12, 0.072], seg=32), GREY, "body")
    k.add("stock", tube([(0, 0.24, 0.32), (0, 0.345, 0.33)], [0.072, 0.034], seg=32), GREY, "tail")
    # the short round beak and the pale lower jaw under it
    k.add("beak", ell((0, -0.29, 0.305), (0.062, 0.07, 0.045), rot=(10, 0, 0)), GREY, "head")
    k.add("jaw", ell((0, -0.265, 0.255), (0.07, 0.07, 0.04), rot=(-8, 0, 0)), CREAM, "head")
    # --- fins -----------------------------------------------------------------------------------------------------
    pectorals(k, (0.115, -0.06, 0.21), (0.6, 0.48, -0.72), (0.1, 0.05, 0.017), GREY)
    fluke(k, (0, 0.35, 0.33), (0.115, 0.06, 0.018), GREY, rise=0.3)
    curl_fin(k, (0.0, 0.07, 0.445), 1.0, GREY)
    # --- the cream underside, from the jaw and the cheeks along the belly, warm tan toward the tail -------------
    edge = lambda y: np.interp(y, [-0.34, -0.2, -0.1, 0.05, 0.2, 0.36], [0.3, 0.31, 0.29, 0.255, 0.28, 0.32])
    k.paint(lambda P: inside(P[:, 2] - edge(P[:, 1]), 0.004), CREAM,
            on=["head", "torso", "rear", "stock", "jaw", "beak"])
    k.paint(lambda P: inside(P[:, 2] - edge(P[:, 1]), 0.004) * inside(0.14 - P[:, 1], 0.01), TAN,
            on=["torso", "rear", "stock"])
    # cream spots: three behind each eye, a few on the flank
    for sx in (1, -1):
        for j, (y, z, r) in enumerate([(-0.07, 0.37, 0.016), (-0.045, 0.35, 0.012), (-0.06, 0.335, 0.011),
                                       (0.14, 0.315, 0.014), (0.165, 0.335, 0.011)]):
            dd = unit(1.0 * sx, 0.05, (z - 0.32) * 2.5)
            k.decal((0.13 * sx, y, z), dd, (r, r), SPOT, eps=0.003, rings=6, segs=28)
    # --- the open smile under the beak: a dark rim, dark red inside, the pink tongue -------------------------
    def mouth(u, v):
        c = np.tile(srgb(MOUTH_IN), (len(u), 1))
        c[(u / 0.62) ** 2 + ((v + 0.38) / 0.45) ** 2 < 1] = srgb(TONGUE)
        c[(u * u + v * v) > 0.82] = srgb(MOUTH_RIM)
        return c
    md = unit(0, -0.6, -0.35)
    k.decal((0, -0.305, 0.275), md, (0.072, 0.034), mouth, up=unit(0, -0.5, 1), eps=0.003,
            outline=polygon([(-1, 0.55), (-0.5, 0.2), (0, 0.1), (0.5, 0.2), (1, 0.55), (0.85, -0.05), (0.45, -0.6),
                             (0, -0.85), (-0.45, -0.6), (-0.85, -0.05)]), rings=12, segs=64)
    # --- the eyes: big and round, high on the head ---------------------------------------------------------------
    de = unit(0.6, -0.62, 0.48)
    E = at_surface(HC, HR, de)
    k.build(voxel=0.0055, smooth=4, band=0.008, wband=0.05)
    k.eye_states(lay_eyes(k, E, de, (0.042, 0.047), GREY))
    k.export(out)


if __name__ == "__main__":
    delfinel(*args())
